CREATE TABLE orders(
  id INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL,
  ordered_at TEXT NOT NULL,
  amount REAL NOT NULL
);

content.starterCode:
SELECT customer_id, MIN(id) AS order_id, MAX(ordered_at) AS ordered_at
FROM orders
GROUP BY customer_id;
